@startuml

class Bettor {
  + Name : string
}

class Race {
  + NumberOfRunners : int
}

class Runner {
  + Name : string
}

class Jockey {
  + Name : string
}

class Bet {
  + Amount : double
  + Odds : double
}

Bettor "1" -- "*" Bet
Race "1" -- "1..*" Runner
Race "1" -- "1" Runner : winner
Runner "1" -- "1" Jockey
Bet "*" -- "1" Race
Bet "*" -- "1" Runner

@enduml

